UPDATE lessons SET title='Year 3, Week 10, Lesson 3: Punctuation review: commas and apostrophes', data=json_patch(data,'{"child_mission":"Commas separate list items or some introductory clauses; apostrophes show contraction or possession. Choose the mark by meaning, not by where a pause happens.","coming_soon":null,"duration_minutes":55,"evidence_instructions":"Save the independent response, specific revisions and both short-answer explanations; record oral evidence for speaking tasks.","explicit_teaching":null,"extension":"Apply the same strategy to an unfamiliar topic or audience, then compare the effect of two different choices.","follow_up_challenges":null,"guided_practice":"PRACTISE BEFORE READING THE FEEDBACK\nPunctuate: ''After lunch we packed maps snacks and coats'' and ''the girls bag was heavy'' (one girl).\n\nFEEDBACK\n''After lunch, we packed maps, snacks and coats.'' ''The girl''s bag was heavy.'' The apostrophe signals one girl''s possession.\n\nCHECK\n''Its'' means belonging to it; ''it''s'' means it is or it has. Not every plural word needs an apostrophe.","hoard_words":null,"independent_task":"INDEPENDENT EVIDENCE\nCorrect eight sentences of your own or from a short passage to demonstrate commas in lists, introductory phrases, one contraction and singular/plural possession. For four corrections, explain what the punctuation communicates.\n\nWrite a short reflection describing one specific revision you made and why.","interactive_activities":null,"learning_area":"English","learning_intention":"Commas separate list items or some introductory clauses; apostrophes show contraction or possession. Choose the mark by meaning, not by where a pause happens.","lesson_number":3,"lesson_role":"Language and spelling","materials":["Paper or typed answer space","Pencil"],"offline_alternative":"Use paper and pencil to complete the original task, then retain a photograph or short parent observation as evidence.","outcome_codes":["EN2-CWT-01"],"parent_notes":"Parent: